      "k86e0f21654a4": "KunThai demande au moment où une fonctionnalité doit accéder. Le refus d’une autorisation facultative ne doit pas bloquer les services non liés.",
      "k614b0a8ba1d9": "KunThai n'a pas pu supprimer cette entreprise pour le moment. Veuillez réessayer.",
