      "k85bf3d9d3114": "KunThai n'a pas pu charger les insights pour ce message pour le moment.",
      "kefa4fc61bfff": "KunThai n'a pas pu envoyer vos commentaires. Votre formulaire a été conservé.",
      "k1b9685e8057a": "KunThai n'a pas pu démarrer une visite d'invité pour le moment. Veuillez réessayer.",
      "k7b72fe78afd1": "KunThai n'a pas pu démarrer l'enregistrement vocal. Fermez les autres applications à l'aide du microphone, puis réessayez.",
      "k2d70d1b8ad29": "KunThai n'a pas pu soumettre votre demande pour le moment.",
