      "k5a1f2d6621e5": "Présentations à l'écran",
      "k01ced6fb0af4": "Allumé. La connexion nécessite votre mot de passe ainsi qu'un code à 6 chiffres provenant de votre application d'authentification.",
      "kc1fab8c9a0f4": "Une fois soumise, la candidature passe en lecture seule. Vous pouvez toujours envoyer un message à l'équipe KunThai à ce sujet et vous pouvez le retirer à tout moment.",
