      "k5dc29a8f9360": "Une invitation vérifiée rapporte 5 crédits. Un petit boost commence à partir de 5 crédits.",
      "kc48829c5f693": "Un espace de travail pour les brouillons, la planification des publications, les téléchargements Swip, la révision en équipe et les performances.",
