      "k29fe7dfd8dc0": "Nous n'avons pas pu nous connecter avec cette adresse e-mail ou ce compte iCloud. Vérifiez le mot de passe ou inscrivez-vous d'abord s'il n'a pas été enregistré.",
      "k57274c82e495": "Nous avons détecté que vous vous trouviez peut-être à proximité d'une frontière internationale. Veuillez confirmer le pays dans lequel vous vous trouvez actuellement : les numéros d'urgence doivent correspondre à votre emplacement réel.",
