      "kb03c2ed8f2aa": "Nous pouvons vous contacter pour vérifier la propriété avant de divulguer des données ou de supprimer un compte.",
      "k4172026634c5": "Nous vous rappelons 7, 3 et 1 jour avant l'expiration. Si un forfait payant expire sans renouvellement, seuls 10 éléments publiés restent visibles. Choisissez lesquels 10 conserver dans votre tableau de bord ; les plus récents sont sélectionnés par défaut. Renouvelez ou mettez à niveau dans les 15 jours pour éviter la suppression définitive des éléments et des brouillons excédentaires.",
